package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaMlDraft1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_bismillah_la_yadurru" to DuaText("എല്ലാ ദോഷങ്ങളിൽ നിന്നും സംരക്ഷണം", "അല്ലാഹുവിൻറെ നാമത്തിൽ, അവൻറെ നാമത്തിൽ ഭൂമിയിലോ ആകാശങ്ങളിലോ യാതൊന്നും ദോഷം ചെയ്യാൻ കഴിയില്ല. അവൻ എല്ലാം കേൾക്കുന്നവനും അറിയുന്നവനുമാണ്.", "രാവിലെയും വൈകുന്നേരവും മൂന്ന് തവണ വീതം.", "രാവിലെയും വൈകുന്നേരവും മൂന്ന് തവണ ആരെങ്കിലും അങ്ങനെ പറഞ്ഞാൽ അവന് ഒരു ദോഷവും സംഭവിക്കില്ല."),
        "dua_raditu_billahi" to DuaText("അല്ലാഹുവിനോട് കർത്താവെന്ന നിലയിൽ സംതൃപ്തി", "അല്ലാഹുവിനെ എന്റെ നാഥനെന്ന നിലയിലും ഇസ്ലാമിനെ എന്റെ മതമായും മുഹമ്മദ് സൽഹുല്ലാഹിനെ എന്റെ പ്രവാചകനെന്ന നിലയിലും ഞാൻ സന്തുഷ്ടനാണ്.", "രാവിലെയും വൈകുന്നേരവും മൂന്ന് തവണ.", "ഉയിർത്തെഴുന്നേൽപിൻറെ നാളിൽ അവനെ പ്രസാദിപ്പിക്കുകയെന്നത് അല്ലാഹുവിൻറെ അവകാശമായി മാറുന്നു."),
        "dua_hasbiyallah" to DuaText("ഹസ്ബിയഅല്ലാഹ് (അല്ലാഹു മതി)", "എനിക്ക് അല്ലാഹു മതി. അവനല്ലാതെ ദൈവമില്ല. ഞാൻ അവനിൽ ഭരമേൽപിക്കുന്നു. അവനാണ് പ്രതാപിയായ സിംഹാസനത്തിൻറെ രക്ഷിതാവ്.", "രാവിലെയും വൈകുന്നേരവും ഏഴ് തവണ.", "ഖുർആനിലെ ഒരു വാക്യം; ഇഹലോകത്തിൻറെയും പരലോകത്തിൻറെയും ആശങ്കകൾക്ക് അല്ലാഹു മതി."),
        "dua_subhanallah_wa_bihamdihi" to DuaText("സുഭൻഅല്ലാഹി വാ ബിഹംദിഹി", "അല്ലാഹുവിന് സ്തുതി, എല്ലാ സ്തുതിയും അവനുതന്നെയാണ്.", "ഒരു ദിവസം നൂറ് തവണ.", "ഒരു ദിവസം നൂറ് തവണ അങ്ങനെ പറയുന്നവൻ കടലിന്റെ നുരയെപ്പോലെയാണെങ്കിലും അവന്റെ പാപങ്ങൾ ക്ഷമിക്കപ്പെടും."),
        "dua_tahleel_100" to DuaText("ലാ ഇലാഹ ഇല്ലല്ലാഹു വാഹ്ദാഹു", "അല്ലാഹുവല്ലാതെ ആരാധനയ്ക്ക് അർഹനായി മറ്റാരുമില്ല. അവൻ ഏകനാണ്, അവന് പങ്കാളികളില്ല. അവന്നാകുന്നു ആധിപത്യം. സ്തുതിയും അവന്നാകുന്നു. അവൻ എല്ലാ കാര്യത്തിനും കഴിവുള്ളവനാകുന്നു.", "ഒരു ദിവസം നൂറ് തവണ അത് പറയുക എന്നത് ഒരു വലിയ ഗുണമാണ്.", "പത്ത് അടിമകളെ മോചിപ്പിച്ചതിൻ്റെ പ്രതിഫലം, എഴുതിയ നൂറ് നല്ല പ്രവൃത്തികൾ, നൂറ് പാപങ്ങൾ മായ്ച്ചുകളയൽ, വൈകുന്നേരം വരെ ഷൈതാനിൽ നിന്നുള്ള സംരക്ഷണം."),
        "dua_leaving_mosque" to DuaText("പള്ളി വിടുന്നു", "അല്ലാഹുവേ, ഞാൻ നിന്നോട് നിൻറെ അനുഗ്രഹം ചോദിക്കുന്നു.", "ഇടതുകൈയ്യുമായി പള്ളിയിൽ നിന്ന് പുറത്തിറങ്ങുമ്പോൾ.", "പള്ളിയിൽ നിന്ന് പുറത്തുപോകുമ്പോൾ അല്ലാഹുവിൻറെ അനുഗ്രഹവും ഉപജീവനവും തേടുക."),
        "dua_after_adhan" to DuaText("അദ്ഹാന് ശേഷം", "അല്ലാഹുവേ, ഈ പൂർണ്ണമായ ആഹ്വാനത്തിൻ്റെയും പ്രതിഷ്ഠിക്കപ്പെടാൻ പോകുന്ന പ്രാർത്ഥനയുടെയും നാഥനേ, മുഹമ്മദ് സല്ലല്ലാഹു അലൈഹി വസിലാഹിനും സദ്ഗുണത്തിനും അർപ്പണമേൽപിക്കുകയും, നീ അദ്ദേഹത്തിന് വാഗ്ദാനം ചെയ്ത സ്തുത്യർഹമായ സ്ഥാനത്തേക്ക് അദ്ദേഹത്തെ ഉയർത്തുകയും ചെയ്യേണമേ.", "അത്താൻ പൂർത്തിയായതിന് ശേഷം.", "ആരെങ്കിലും ഇങ്ങനെ പറഞ്ഞാൽ വിധിദിവസത്തിൽ നബി (സ) യുടെ ശുപാർശ നൽകപ്പെടും."),
        "dua_after_salah_istighfar" to DuaText("ഫർദ് സലായ്ക്ക് ശേഷം", "ഞാൻ അല്ലാഹുവോട് പാപമോചനം തേടുന്നു. (മൂന്ന് തവണ) അല്ലാഹുവേ, നീ സലാം ആകുന്നു. നിന്നിൽനിന്ന് സമാധാനമുണ്ട്. പ്രതാപവും ബഹുമാനവും ഉള്ളവനേ, നീ അനുഗ്രഹിക്കപ്പെട്ടവനാണ്.", "സലാം കഴിഞ്ഞ് ഉടൻ തന്നെ.", "എല്ലാ നിർബന്ധിത പ്രാർത്ഥനയ്ക്കും ശേഷം പ്രവാചകൻ (സ) ഇത് പാരായണം ചെയ്തു."),
        "dua_after_salah_help_dhikr" to DuaText("നിന്നെ ഓർമ്മിക്കാൻ എന്നെ സഹായിക്കൂ.", "അല്ലാഹുവേ, നിന്നെ ഓർമ്മിക്കാനും നന്ദി പറയാനും ഏറ്റവും മികച്ച രീതിയിൽ നിന്നെ ആരാധിക്കാനും എന്നെ സഹായിക്കണമേ.", "ഓരോ പ്രാർത്ഥനയ്ക്കും ശേഷം-നബി (സ) മുഹമ്മദിന് അത് പറയാൻ ഉപദേശിച്ചു.", "പ്രവാചകൻറെ ഒരു പ്രത്യേക ഉപദേശം-ആരാധനയിലെ മികവും സ്ഥിരതയും."),
        "dua_sleep_tasbeeh" to DuaText("ഉറങ്ങുന്നതിനുമുമ്പ് തസ്ബെഹ്-ഇ-ഫാത്തിമി", "അല്ലാഹുവിന് സ്തുതി (33), എല്ലാ സ്തുതിയും അല്ലാഹുവിനു (33), അല്ലാഹു ഏറ്റവും വലിയവനാണ് (34).", "ഉറങ്ങുന്നതിനുമുമ്പ്-നബി (സ) അത് ഫാത്തിമയെയും അലിയെയും (റ) പഠിപ്പിച്ചു.", "ഒരു ദാസനെക്കാൾ നിങ്ങൾക്ക് ഇത് നല്ലതാണെന്ന് പ്രവാചകൻ പറഞ്ഞു."),
        "dua_sleep_qina_adhab" to DuaText("ശിക്ഷയിൽ നിന്നുള്ള സംരക്ഷണം", "അല്ലാഹുവേ, നിൻറെ ദാസന്മാരെ ഉയിർത്തെഴുന്നേൽപ്പിക്കുന്ന ദിവസം നിൻറെ ശിക്ഷയിൽ നിന്ന് എന്നെ സംരക്ഷിക്കണമേ.", "മൂന്ന് തവണ, വലത് കൈ കവിളിന് കീഴിൽ വയ്ക്കുക.", "ഉറക്കത്തെ മരണത്തിൻ്റെയും പരലോകത്തിനായുള്ള തയ്യാറെടുപ്പുകളുടെയും ഓർമ്മപ്പെടുത്തലാക്കുന്നു."),
        "dua_bad_dream" to DuaText("ഒരു മോശം സ്വപ്നത്തിന് ശേഷം", "ശപിക്കപ്പെട്ട ഷൈത്താൻ എന്നവനിൽനിന്ന് ഞാൻ അല്ലാഹുവിൽ അഭയം തേടുന്നു.", "ഒരു മോശം സ്വപ്നത്തിന് ശേഷംഃ മൂന്ന് തവണ ഇടതുവശത്ത് ചെറുതായി തുപ്പി, തുടർന്ന് മറുവശത്തേക്ക് തിരിക്കുക.", "ആ മോശം സ്വപ്നം നിങ്ങളെ ഉപദ്രവിക്കില്ല; അതിനെക്കുറിച്ച് ആരോടും പറയരുത്."),
        "dua_ya_hayyu_ya_qayyum" to DuaText("യാ ഹയ്യൂ യാ കയ്യും", "ഓ നിത്യജീവിയേ, എല്ലാവരുടെയും പരിപാലകനേ, അങ്ങയുടെ കാരുണ്യത്താൽ ഞാൻ സഹായം തേടുന്നു.", "ഒരു കാര്യം വളരെ ഭാരമായിത്തീരുമ്പോൾ.", "നബി (സ) യെ വല്ലതും വിഷമിപ്പിക്കുമ്പോഴെല്ലാം അദ്ദേഹം ഇത് പറയുമായിരുന്നു."),
        "dua_entering_market" to DuaText("മാർക്കറ്റിലേക്ക് പ്രവേശിക്കുന്നു", "അല്ലാഹുവല്ലാതെ ആരാധനയ്ക്ക് അർഹനായി മറ്റാരുമില്ല. അവൻ ഏകനാണ്, അവന് പങ്കാളികളില്ല. അവന്നാകുന്നു ആധിപത്യം. അവന്നാകുന്നു സ്തുതി. അവൻ ജീവൻ നൽകുകയും മരിപ്പിക്കുകയും ചെയ്യുന്നു. അവൻ നിത്യജീവനാണ്. ഒരിക്കലും മരിക്കുകയുമില്ല. അവൻറെ കയ്യിൽ എല്ലാം നന്നായിരിക്കുന്നു. അവൻ എല്ലാ കാര്യത്തിനും കഴിവുള്ളവനാകുന്നു.", "വിപണിയിൽ പ്രവേശിക്കുമ്പോൾ.", "ഹദീസിൽ അതിന് (ഒരു ദശലക്ഷം സൽകർമ്മങ്ങൾക്ക്) വലിയ പ്രതിഫലം നൽകുന്നതായി പരാമർശിക്കുന്നു."),
        "dua_adam_forgiveness" to DuaText("ആദം നബിയുടെ (അ. സ.) ദുആ", "ഞങ്ങളുടെ രക്ഷിതാവേ, ഞങ്ങൾ നമ്മോടുതന്നെ അനീതി ചെയ്തിരിക്കുന്നു. നീ ഞങ്ങൾക്ക് മാപ്പ് നൽകുകയും ഞങ്ങളോട് കരുണ കാണിക്കുകയും ചെയ്തില്ലെങ്കിൽ തീർച്ചയായും ഞങ്ങൾ നഷ്ടക്കാരുടെ കൂട്ടത്തിലായിരിക്കും.", "ആദാമിന്റെയും ഹാവ്വയുടെയും (എ. എസ്) അനുതാപത്തിൻറെ ദുആ.", "മനുഷ്യരാശിയുടെ ആദ്യ പശ്ചാത്താപം-അല്ലാഹു അത് സ്വീകരിച്ചു."),
        "dua_abu_bakr" to DuaText("ദുആ അബൂബക്കറിനെ (റ) പഠിപ്പിച്ചു.", "അല്ലാഹുവേ, ഞാൻ എന്നോട് തന്നെ വല്ലാത്ത അനീതി ചെയ്തിരിക്കുന്നു. നിന്നല്ലാതെ ആരും പാപങ്ങൾ പൊറുക്കുന്നില്ല. അതിനാൽ നീ എന്നോട് തന്നെ പാപമോചനം ചെയ്യേണമേ. എന്നോട് കരുണ കാണിക്കണമേ. തീർച്ചയായും നീ ഏറെ പൊറുക്കുന്നവനും കരുണാനിധിയുമാകുന്നു.", "പ്രവാചകൻ സൽഹഅലിഹ് വസ്ലം അബൂബക്കർ അസ്-സിദ്ദിഖിനെ (റ) പ്രാർത്ഥനയിൽ (താഷാഹുദിനുശേഷം) പറയാൻ പഠിപ്പിച്ചു.", "പ്രാർത്ഥനയുടെ അവസാനത്തിനായി ഒരു സുന്നത്ത് ദുആ."),
        "dua_astaghfirullah_atubu" to DuaText("ദിനപത്രമായ ഇസ്തിഗ്ഫർ", "ഞാൻ അല്ലാഹുവോട് പാപമോചനം തേടുകയും അവനോട് പശ്ചാത്തപിക്കുകയും ചെയ്യുന്നു.", "നബി (സ) ഒരു ദിവസം എഴുപതിലേറെ തവണ പാപമോചനം തേടിയിട്ടുണ്ട്.", "നബി (സ) പറഞ്ഞുഃ ഞാൻ അല്ലാഹുവോട് പാപമോചനം തേടുകയും ഒരു ദിവസം എഴുപതിലേറെ തവണ അവനോട് പശ്ചാത്തപിക്കുകയും ചെയ്യുന്നു."),
        "dua_laylatul_qadr" to DuaText("ലയലത്ത് അൽ-ഖാദറിനായി ദുആ", "അല്ലാഹുവേ, നീ ഏറെ പൊറുക്കുന്നവനും ക്ഷമിക്കാൻ ഇഷ്ടപ്പെടുന്നവനുമാണ്, അതിനാൽ എന്നോട് ക്ഷമിക്കണമേ.", "ലയലത്ത് അൽ ഖാദറിനായി ആയിഷയെ (റ) പഠിപ്പിച്ചു.", "റമദാൻ, ലൈലത്ത് അൽ ഖാദർ എന്നിവയുടെ അവസാന രാത്രികൾക്കുള്ള പ്രത്യേക ദുആ."),
        "dua_family_coolness" to DuaText("കണ്ണുകളുടെ തണുപ്പ് (പങ്കാളിയും കുട്ടികളും)", "ഞങ്ങളുടെ കർത്താവേ, ഞങ്ങളുടെ ഇണകളിൽ നിന്നും ഞങ്ങളുടെ സന്തതികളിൽ നിന്നും ഞങ്ങളുടെ കണ്ണുകളുടെ തണുപ്പ് നൽകുകയും ഞങ്ങളെ നീതിമാന്മാരുടെ നേതാക്കളായി മാറ്റുകയും ചെയ്യേണമേ.", "നീതിമാനായ ഒരു പങ്കാളിക്കും കുട്ടികൾക്കുമുള്ള ഖുർആൻ ദുആ.", "വീട്ടിൽ സമാധാനത്തിനും നീതിമാന്മാരായ കുട്ടികൾക്കും വേണ്ടി."),
        "dua_righteous_children" to DuaText("നീതിമാനായ സന്തതികൾക്ക്", "എൻറെ രക്ഷിതാവേ, എനിക്ക് നിൻറെ പക്കൽ നിന്ന് ശുദ്ധമായ സന്തതികൾ നൽകേണമേ. തീർച്ചയായും നീ യാചന കേൾക്കുന്നവനാകുന്നു.", "സകരിയ (അ. സ.) പ്രവാചകൻറെ ദുആ.", "കുട്ടികൾ തേടുന്നവർക്കുള്ള ഖുർആൻ ദുആ."),
        "dua_ibrahim_prayer_family" to DuaText("പ്രാർത്ഥനയുടെ സ്ഥാപകർ", "എൻറെ രക്ഷിതാവേ, എന്നെ പ്രാർത്ഥനയുടെ സ്ഥാപകനാക്കുകയും എൻറെ സന്തതികളിൽ നിന്ന് എന്നെ സ്ഥാപിക്കുകയും ചെയ്യേണമേ. എൻറെ രക്ഷിതാവേ, എൻറെ പ്രാർത്ഥന സ്വീകരിക്കണമേ. എൻറെ രക്ഷിതാവേ, എൻറെ മാതാപിതാക്കൾക്കും സത്യവിശ്വാസികൾക്കും കണക്ക് നിശ്ചയിക്കുന്ന ദിവസം നീ പൊറുത്തുതരേണമേ.", "തനിക്കും അദ്ദേഹത്തിൻ്റെ പിൻഗാമികൾക്കും വേണ്ടി പ്രവാചകൻ ഇബ്രാഹിം (അ. സ.) യുടെ ദുആ.", "സാധാരണയായി പ്രാർത്ഥനയുടെ അവസാനത്തിൽ പാരായണം ചെയ്യപ്പെടുന്നു."),
        "dua_newlywed" to DuaText("നവദമ്പതികളെ അഭിനന്ദിക്കുന്നു", "അല്ലാഹു നിങ്ങളെ അനുഗ്രഹിക്കുകയും നിങ്ങൾക്ക് അനുഗ്രഹങ്ങൾ നൽകുകയും നിങ്ങളെ രണ്ടുപേരെയും നന്മയോടെ ഒന്നിപ്പിക്കുകയും ചെയ്യട്ടെ.", "ഒരാളുടെ വിവാഹത്തിന് അഭിനന്ദനം അറിയിക്കുമ്പോൾ.", "വിവാഹത്തിന് സുന്നത്ത് അഭിനന്ദനങ്ങൾ."),
        "dua_before_eating" to DuaText("ഭക്ഷണം കഴിക്കുന്നതിന് മുമ്പ്", "അല്ലാഹുവിൻറെ നാമത്തിൽ. (മറന്നുപോയാൽഃ) അല്ലാഹുവിൻറെ നാമത്തിൽ, അതിൻറെ തുടക്കത്തിലും അവസാനത്തിലും.", "ഭക്ഷണം കഴിക്കുന്നതിന് മുമ്പ്. നിങ്ങൾ മറന്നാൽ, അത് ഭാഗികമായി പറയുക.", "ബിസ്മില്ലാഹ് പറയുന്നത് ഷൈതാനെ ഭക്ഷണം പങ്കിടുന്നതിൽ നിന്ന് തടയുന്നു."),
        "dua_after_eating" to DuaText("ഭക്ഷണം കഴിച്ചതിനുശേഷം", "എനിക്ക് ഇത് നൽകുകയും എന്റെ ഭാഗത്തുനിന്ന് ഒരു ശക്തിയോ അധികാരമോ ഇല്ലാതെ എനിക്ക് നൽകുകയും ചെയ്ത അല്ലാഹുവിനു എല്ലാ സ്തുതിയും.", "ഭക്ഷണം കഴിച്ചതിനുശേഷം.", "അത് ക്ഷമിക്കപ്പെട്ടുവെന്ന് പറയുന്നയാളുടെ മുൻകാല പാപങ്ങൾ."),
        "dua_host" to DuaText("ആതിഥേയർക്ക്", "അല്ലാഹുവേ, നീ അവർക്ക് നൽകിയതിൽ അവരെ അനുഗ്രഹിക്കേണമേ. അവരോട് നീ ക്ഷമിക്കണമേ. അവരോട് കരുണ കാണിക്കണമേ.", "ആതിഥേയനെ സംബന്ധിച്ചിടത്തോളം, ആരുടെയെങ്കിലും വീട്ടിൽ ഭക്ഷണം കഴിച്ചതിന് ശേഷം.", "സുന്നാ രീതിയിൽ ആതിഥേയർക്ക് നന്ദി പറയുന്നു."),
        "dua_breaking_fast" to DuaText("ഉപവാസം അവസാനിപ്പിക്കുമ്പോൾ", "ദാഹം പോയി, സിരകൾ നനഞ്ഞു, അല്ലാഹു ഉദ്ദേശിക്കുന്നുവെങ്കിൽ പ്രതിഫലം സ്ഥിരീകരിക്കപ്പെടുന്നു.", "ഇഫ്താർ സമയത്ത്.", "നബി (സ) വ്രതം അവസാനിപ്പിക്കവേയാണ് ഇക്കാര്യം പറഞ്ഞത്."),
        "dua_new_clothes" to DuaText("പുതിയ വസ്ത്രങ്ങൾ ധരിക്കുക", "അല്ലാഹുവേ, എല്ലാ സ്തുതിയും നിന്റേതാണ്. നീ എന്നെ ഇത് ധരിപ്പിച്ചു. അതിൻറെ നന്മയും നന്മയും ഞാൻ നിന്നോടു ചോദിക്കുന്നു. അതിൻറെ തിന്മയിൽ നിന്നും തിന്മയിൽ നിന്നും ഞാൻ നിന്നിൽ അഭയം തേടുന്നു.", "ഒരു പുതിയ വസ്ത്രം ധരിക്കുമ്പോൾ (ഷർട്ട് അല്ലെങ്കിൽ തലപ്പാവ് പോലുള്ളവ).", "നബിയായ സൽഹഅലിഹ് വസ്ലം ഒരു പുതിയ വസ്ത്രം ധരിക്കുമ്പോഴാണ് ഈ ദുആ ചെയ്തത്. (വസ്ത്രധാരണത്തിനുള്ള ദൈനംദിന ദുആ'വസ്ത്രം ധരിക്കുക'എന്നതിൻ്റെ കീഴിലാണ്)"),
        "dua_rabbana_atina" to DuaText("ഇഹലോകത്തും പരലോകത്തും നന്മയുണ്ട്.", "ഞങ്ങളുടെ രക്ഷിതാവേ, ഞങ്ങൾക്ക് ഇഹലോകത്ത് നന്മയും പരലോകത്ത് നന്മയും നൽകുകയും നരകശിക്ഷയിൽ നിന്ന് ഞങ്ങളെ സംരക്ഷിക്കുകയും ചെയ്യേണമേ.", "നബി (സ) യുടെ ദുആവാണ് ഏറ്റവും കൂടുതൽ ചെയ്യപ്പെട്ടത്.", "ഇഹലോകത്തിലെയും പരലോകത്തിലെയും എല്ലാ നന്മയും ശേഖരിക്കുന്ന ഒരു ദുആ."),
        "dua_rabbi_zidni_ilma" to DuaText("അറിവ് വർദ്ധിപ്പിക്കുക", "എൻറെ കർത്താവേ, എന്നെ അറിവോടെ വർദ്ധിപ്പിക്കണമേ.", "അറിവ് വർദ്ധിപ്പിക്കുന്നതിനായി.", "അറിവല്ലാതെ മറ്റൊന്നും വർദ്ധിപ്പിക്കരുതെന്ന് അല്ലാഹു പ്രവാചകനോട് കൽപിച്ചു."),
        "dua_musa_sharh_sadr" to DuaText("നെഞ്ച് തുറക്കുന്നത് (മൂസ എ. എസ്)", "എൻറെ കർത്താവേ, എനിക്കുവേണ്ടി എൻറെ നെഞ്ച് നീട്ടുക, എനിക്കുവേണ്ടി എൻറെ ജോലി ലഘൂകരിക്കുക, എൻറെ സംസാരം അവർക്ക് മനസ്സിലാകാനായി എൻറെ നാവിൽ നിന്ന് മുടി തുറക്കുക.", "ഒരു പരീക്ഷയ്ക്ക് മുമ്പ്, ഒരു പ്രസംഗം അല്ലെങ്കിൽ ഏതെങ്കിലും ബുദ്ധിമുട്ടുള്ള ജോലി.", "പ്രവാചകൻ മൂസ (അ. സ.) യുടെ ദുആ-ഹൃദയത്തിൻറെ ശാന്തതയും ഒരാളുടെ ജോലിയിൽ എളുപ്പവും."),
        "dua_la_tuzigh" to DuaText("ഹൃദയത്തിൻ്റെ സ്ഥിരത", "ഞങ്ങളുടെ രക്ഷിതാവേ, നീ ഞങ്ങളെ നേർവഴിയിലാക്കിയതിനുശേഷം ഞങ്ങളുടെ ഹൃദയങ്ങൾ വ്യതിചലിക്കാതിരിക്കുകയും, നിൻറെ പക്കൽ നിന്ന് ഞങ്ങൾക്ക് കരുണ നൽകുകയും ചെയ്യേണമേ. തീർച്ചയായും നീയാണ് നൽകുന്നവൻ.", "മാർഗനിർദേശത്തിന്മേലുള്ള സ്ഥിരതയ്ക്ക്.", "വിശ്വാസത്തിൽ ഉറച്ചുനിൽക്കുന്നതിനുള്ള ഒരു ദുആ."),
        "dua_ya_muqallib" to DuaText("ഓ ഹൃദയങ്ങളുടെ ഓർമ്മകൾ", "ഹൃദയങ്ങളുടെ ഓ തുണയായവരേ, അങ്ങയുടെ മതത്തിൽ എൻറെ ഹൃദയം ഉറച്ചുനിൽക്കട്ടെ.", "നബി (സ) പലപ്പോഴും ഈ ദുആ നടത്തിയിരുന്നു.", "ഉം സലമ (റ) പറയുന്നതനുസരിച്ച്, പ്രവാചകൻ സൽഹഅല്ലാഹുൽ മുസ്ലിമാണ് ഏറ്റവും കൂടുതൽ ദുആ ചെയ്തത്."),
        "dua_la_tuakhidhna" to DuaText("സൂറ അൽ ബഖറയുടെ അവസാന വചനങ്ങൾ", "ഞങ്ങളുടെ രക്ഷിതാവേ, ഞങ്ങൾ മറന്നുപോകുകയോ തെറ്റ് ചെയ്യുകയോ ചെയ്താൽ നീ ഞങ്ങളെ ശിക്ഷിക്കരുത്. ഞങ്ങളുടെ രക്ഷിതാവേ, ഞങ്ങളുടെ മേൽ നീ ചുമത്തിയ ഭാരം പോലെ ഒരു ഭാരവും ഞങ്ങളുടെ മേൽ നീ ചുമത്തരുത്. ഞങ്ങളുടെ രക്ഷിതാവേ, ഞങ്ങൾക്ക് താങ്ങാനാവാത്ത ഭാരം നീ ഞങ്ങൾക്ക് ചുമത്തരുത്. ഞങ്ങളോട് ക്ഷമിക്കണമേ. ഞങ്ങൾക്ക് നീ പൊറുത്തുതരേണമേ. ഞങ്ങളോട് കരുണ കാണിക്കണമേ. നീ ഞങ്ങളുടെ രക്ഷകനാണ്. അതിനാൽ സത്യനിഷേധികളായ ജനങ്ങളിൽ നിന്ന് ഞങ്ങളെ സഹായിക്കണമേ.", "ഉറങ്ങുന്നതിനുമുമ്പുള്ള രാത്രി-സൂറ അൽ ബഖറയിലെ അവസാന രണ്ട് വാക്യങ്ങൾ.", "സൂറ അൽ ബഖറയിലെ അവസാനത്തെ രണ്ട് വാക്യങ്ങൾ രാത്രിയിൽ ആരെങ്കിലും പാരായണം ചെയ്താൽ അവർക്ക് മതിയാകും."),
        "dua_visiting_sick" to DuaText("രോഗിയെ സന്ദർശിക്കുന്നു", "നിങ്ങളെ സുഖപ്പെടുത്തണമെന്ന് ഞാൻ ശക്തനും ശക്തനുമായ അല്ലാഹുവോട്, ശക്തനായ സിംഹാസനത്തിൻറെ രക്ഷിതാവിനോട്, അഭ്യർത്ഥിക്കുന്നു.", "രോഗികളെ സന്ദർശിക്കുമ്പോൾ ഏഴ് തവണ.", "മരണകാലം വന്നിട്ടില്ലെങ്കിൽ അല്ലാഹു അവനെ സുഖപ്പെടുത്തും."),
        "dua_ruqyah_pain" to DuaText("ശാരീരിക വേദനയ്ക്ക്", "എനിക്ക് തോന്നുന്നതിൻ്റെയും ഭയപ്പെടുന്നതിൻ്റെയും തിന്മയിൽ നിന്ന് ഞാൻ അല്ലാഹുവിലും അവൻറെ ശക്തിയിലും അഭയം തേടുന്നു.", "വേദനയുള്ളിടത്ത് നിങ്ങളുടെ കൈ വയ്ക്കുക, മൂന്ന് തവണ ബിസ്മില്ല എന്ന് പറയുക, തുടർന്ന് ഈ ദുആ ഏഴ് തവണ ചെയ്യുക.", "നബി (സ) അത് ഉസ്മാൻ ഇബ്നു അബിൽ-അസ് (റ) നെ വേദനയ്ക്കായി പഠിപ്പിച്ചു."),
        "dua_ruqyah_nabawi" to DuaText("രോഗികൾക്കുള്ള പ്രവാചകമായ റുഖിയ", "മനുഷ്യരുടെ രക്ഷിതാവായ അല്ലാഹുവേ, നീ ദോഷം നീക്കുകയും, രോഗശാന്തി നൽകുകയും ചെയ്യേണമേ. നീയാണ് രോഗശാന്തി നൽകുന്നവൻ. നിൻറെ രോഗശാന്തിയല്ലാതെ ചികിത്സയില്ല. ഒരു രോഗവും ഉപേക്ഷിക്കാത്ത ഒരു ചികിത്സ.", "രോഗിയുടെ മേൽ കൈ വെക്കുമ്പോൾ.", "തന്റെ കുടുംബത്തിലെ രോഗികളായ അംഗങ്ങളെ സന്ദർശിക്കുമ്പോഴാണ് പ്രവാചകൻ ഇത് പാരായണം ചെയ്തത്."),
        "dua_kalimat_tammat" to DuaText("തികഞ്ഞ വാക്കുകളിൽ അഭയം തേടുക", "അവൻ സൃഷ്ടിച്ചതിൻറെ തിന്മയിൽ നിന്ന് ഞാൻ അല്ലാഹുവിൻറെ പൂർണ്ണമായ വചനങ്ങളിൽ അഭയം തേടുന്നു.", "ഒരു സ്ഥലത്തോ വൈകുന്നേരത്തോ നിർത്തുമ്പോൾ.", "ആരെങ്കിലും ഒരു സ്ഥലത്ത് നിർത്തി ഇത് പറഞ്ഞാൽ, അവൻ അത് ഉപേക്ഷിക്കുന്നതുവരെ ഒന്നും അവനെ ഉപദ്രവിക്കില്ല."),
        "dua_evil_eye" to DuaText("കുട്ടികൾക്കുള്ള സംരക്ഷണം (ദുഷ്ട കണ്ണ്)", "എല്ലാ പിശാചുകളിൽ നിന്നും എല്ലാ വിഷവസ്തുക്കളിൽ നിന്നും എല്ലാ ദോഷകരമായ കണ്ണുകളിൽ നിന്നും അല്ലാഹുവിൻറെ പൂർണ്ണമായ വാക്കുകളിൽ ഞാൻ നിങ്ങൾക്ക് സംരക്ഷണം തേടുന്നു.", "ഹസൻറെയും ഹുസൈൻറെയും (റ) മേൽ നബി (സ) ഇത് പാരായണം ചെയ്തു.", "കുട്ടികളെ ദുർദൃഷ്ടിയിൽ നിന്നും ദോഷത്തിൽ നിന്നും സംരക്ഷിക്കുന്നതിനുള്ള ഒരു സുന്നത്ത് ദുആ (ഒരു കുട്ടിക്ക്'ഉധുക'എന്ന് പറയുന്നു)."),
        "dua_seeing_afflicted" to DuaText("ആരെയെങ്കിലും വിചാരണയ്ക്കായി കാണുന്നത്", "നിങ്ങളെ പരീക്ഷിച്ചതിൽ നിന്ന് എന്നെ രക്ഷിക്കുകയും തൻറെ സൃഷ്ടിയിൽ ഭൂരിഭാഗത്തേക്കാളും എനിക്ക് അനുഗ്രഹം നൽകുകയും ചെയ്ത അല്ലാഹുവിനു സ്തുതി.", "ആരെയെങ്കിലും വിചാരണയ്ക്കു വിധേയനാക്കുമ്പോൾ (അത് നിശബ്ദമായി സ്വയം പറയുക).", "ആ വിചാരണയ്ക്കുശേഷം അത് സുരക്ഷിതമാണെന്ന് പറയുന്നവർ."),
        "dua_istikhara" to DuaText("സലാത്ത് അൽ-ഇസ്തിഖറ", "അല്ലാഹുവേ, ഞാൻ നിൻറെ അറിവിലൂടെ നന്മ തേടുന്നു. നിൻറെ ശക്തിയിലൂടെ ഞാൻ കഴിവുകൾ തേടുന്നു. നിൻറെ മഹത്തായ അനുഗ്രഹം ഞാൻ നിന്നോടു ചോദിക്കുന്നു. നിനക്ക് ശക്തിയുണ്ട്. എനിക്കതിനൊന്നും കഴിവില്ല. നിനക്കറിയാമല്ലോ. എനിക്കറിയില്ല. നീ അദൃശ്യകാര്യങ്ങൾ അറിയുന്നവനും ആകുന്നു. അല്ലാഹുവേ, നിനക്ക് ഈ കാര്യം (മനസ്സിൽ കൊണ്ടുവരിക) എൻറെ മതത്തിനും എൻറെ ജീവിതത്തിനും എൻറെ അന്ത്യത്തിനും നല്ലതാണെങ്കിൽ എനിക്കത് വിധിച്ചുതരിക. എനിക്കത് എളുപ്പമാക്കുകയും എന്നിൽ അനുഗ്രഹം നൽകുകയും ചെയ്യുക. നിനക്ക് അറിയാമെങ്കിൽ ഈ കാര്യം എൻറെ മതത്തിനും എൻറെ ജീവിതത്തിനും എൻറെ അന്ത്യത്തിനും ദോഷകരമാണെങ്കിൽ എന്നിൽ നിന്ന് അത് തിരിക്കുകയും എന്നിൽ നിന്ന് എന്നെ പിന്തിരിപ്പിക്കുകയും, എനിക്ക് അത് എവിടെ ആയാലും നന്മയെന്താണെന്ന് വിധിച്ചുതരികയും ചെയ്യുക.", "സ്വമേധയാ പ്രാർത്ഥിക്കുന്ന രണ്ട് റാഖുകൾക്ക് ശേഷം, അനുവദനീയമായ ഒരു കാര്യത്തിൽ ഏറ്റവും മികച്ചത് അന്വേഷിക്കുക.", "ഖുർആനിൻറെ ഒരു സൂറത്ത് പഠിപ്പിച്ചതിനാൽ നബി (സ) എല്ലാ കാര്യങ്ങളിലും പങ്കാളികളെ ഇസ്തികർ പഠിപ്പിച്ചു."),
    )
}
